CREATE DATABASE IF NOT EXISTS retailflow CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE retailflow;
SET FOREIGN_KEY_CHECKS=0; DROP TABLE IF EXISTS stock_movements,purchase_items,purchases,invoice_items,invoices,cash_sessions,products,categories,customers,suppliers,users; SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),username VARCHAR(50) UNIQUE,password_hash VARCHAR(255),role ENUM("admin","cashier","warehouse") DEFAULT "cashier",is_active TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name_ar VARCHAR(100),name_en VARCHAR(100));
CREATE TABLE products(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id INT UNSIGNED NULL,sku VARCHAR(80) UNIQUE,barcode VARCHAR(80) UNIQUE NULL,name_ar VARCHAR(180),name_en VARCHAR(180),purchase_price DECIMAL(14,2) DEFAULT 0,sale_price DECIMAL(14,2) DEFAULT 0,stock_qty DECIMAL(14,3) DEFAULT 0,min_stock DECIMAL(14,3) DEFAULT 5,unit VARCHAR(30) DEFAULT "piece",is_active TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,INDEX(name_en),INDEX(barcode),INDEX(stock_qty));
CREATE TABLE customers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160),phone VARCHAR(40),address VARCHAR(255));
CREATE TABLE suppliers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160),phone VARCHAR(40),address VARCHAR(255),tax_no VARCHAR(80),balance DECIMAL(14,2) DEFAULT 0);
CREATE TABLE cash_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED,opened_at DATETIME,opening_cash DECIMAL(14,2),closed_at DATETIME NULL,closing_cash DECIMAL(14,2) NULL,expected_cash DECIMAL(14,2) NULL,cash_sales DECIMAL(14,2) DEFAULT 0,card_sales DECIMAL(14,2) DEFAULT 0,other_sales DECIMAL(14,2) DEFAULT 0,sales_count INT DEFAULT 0,status ENUM("open","closed") DEFAULT "open",FOREIGN KEY(user_id) REFERENCES users(id),INDEX(status));
CREATE TABLE invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_no VARCHAR(40) UNIQUE,customer_id INT UNSIGNED NULL,user_id INT UNSIGNED,cash_session_id BIGINT UNSIGNED NULL,subtotal DECIMAL(14,2),discount DECIMAL(14,2),total DECIMAL(14,2),paid DECIMAL(14,2),change_amount DECIMAL(14,2),payment_method ENUM("cash","card","other") DEFAULT "cash",status ENUM("paid","partial","unpaid","cancelled") DEFAULT "paid",created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(cash_session_id) REFERENCES cash_sessions(id) ON DELETE SET NULL,INDEX(created_at));
CREATE TABLE invoice_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED,product_id INT UNSIGNED,product_name VARCHAR(180),sku VARCHAR(80),qty DECIMAL(14,3),unit_price DECIMAL(14,2),line_total DECIMAL(14,2),FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE purchases(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,purchase_no VARCHAR(40) UNIQUE,supplier_id INT UNSIGNED,user_id INT UNSIGNED,subtotal DECIMAL(14,2),discount DECIMAL(14,2),total DECIMAL(14,2),paid DECIMAL(14,2),balance DECIMAL(14,2),status ENUM("paid","partial","unpaid"),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(supplier_id) REFERENCES suppliers(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE purchase_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,purchase_id BIGINT UNSIGNED,product_id INT UNSIGNED,qty DECIMAL(14,3),unit_cost DECIMAL(14,2),line_total DECIMAL(14,2),FOREIGN KEY(purchase_id) REFERENCES purchases(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE stock_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id INT UNSIGNED,user_id INT UNSIGNED,type ENUM("in","out","adjustment"),qty DECIMAL(14,3),reference_type VARCHAR(40),reference_id BIGINT UNSIGNED,note VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(user_id) REFERENCES users(id));
